package be.winnetrie.mod.simpleserverutilities.moderation;
import net.minecraft.network.RegistryFriendlyByteBuf;import net.minecraft.world.Container;import net.minecraft.world.SimpleContainer;import net.minecraft.world.entity.player.Inventory;import net.minecraft.world.entity.player.Player;import net.minecraft.world.inventory.AbstractContainerMenu;import net.minecraft.world.inventory.Slot;import net.minecraft.world.item.ItemStack;
/** Real editable target inventory/ender chest plus the administrator inventory. */
public final class PlayerInventoryAdminMenu extends AbstractContainerMenu{public static final int INVENTORY_SLOTS=41,ENDER_SLOTS=27;private final SimpleContainer target;private final Inventory admin;private final String targetId,targetName,mode;private final Runnable saver;private final int targetSlots;
 public PlayerInventoryAdminMenu(int id,Inventory inv,RegistryFriendlyByteBuf b){this(id,inv,new SimpleContainer(b.readVarInt()),b.readUtf(64),b.readUtf(64),b.readUtf(16),()->{});}
 public PlayerInventoryAdminMenu(int id,Inventory inv,SimpleContainer target,String targetId,String targetName,String mode,Runnable saver){super(ModModerationMenus.PLAYER_INVENTORY.get(),id);this.target=target;this.admin=inv;this.targetId=targetId;this.targetName=targetName;this.mode=mode;this.saver=saver;this.targetSlots=target.getContainerSize();target.startOpen(inv.player);int rows=(targetSlots+8)/9;for(int i=0;i<targetSlots;i++)addSlot(new Slot(target,i,17+(i%9)*18,34+(i/9)*18));int baseY=34+rows*18+22;for(int r=0;r<3;r++)for(int c=0;c<9;c++)addSlot(new Slot(inv,c+r*9+9,17+c*18,baseY+r*18));for(int c=0;c<9;c++)addSlot(new Slot(inv,c,17+c*18,baseY+58));}
 public String targetName(){return targetName;}public String mode(){return mode;}public int targetSlots(){return targetSlots;}@Override public boolean stillValid(Player p){return true;}@Override public void removed(Player p){super.removed(p);target.stopOpen(p);saver.run();}@Override public ItemStack quickMoveStack(Player p,int index){if(index<0||index>=slots.size())return ItemStack.EMPTY;Slot slot=slots.get(index);if(!slot.hasItem())return ItemStack.EMPTY;ItemStack original=slot.getItem();ItemStack copy=original.copy();if(index<targetSlots){if(!moveItemStackTo(original,targetSlots,slots.size(),true))return ItemStack.EMPTY;}else if(!moveItemStackTo(original,0,targetSlots,false))return ItemStack.EMPTY;if(original.isEmpty())slot.set(ItemStack.EMPTY);else slot.setChanged();return copy;}
}
